// Simple "Space Junk Dodger" game
// Canvas with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  // Ship definition
  const ship = {
    x: width / 2,
    y: height - 60,
    size: 20,
    speed: 4,
    dx: 0,
    dy: 0,
  };

  // Asteroid list
  const asteroids = [];
  const asteroidSpawnRate = 1000; // ms
  const asteroidSpeed = 2;
  let lastSpawn = 0;
  let gameOver = false;

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function update(dt) {
    if (gameOver) return;
    // Move ship based on arrow keys
    ship.dx = 0; ship.dy = 0;
    if (keys['ArrowLeft']) ship.dx = -ship.speed;
    if (keys['ArrowRight']) ship.dx = ship.speed;
    if (keys['ArrowUp']) ship.dy = -ship.speed;
    if (keys['ArrowDown']) ship.dy = ship.speed;
    ship.x = Math.max(ship.size, Math.min(width - ship.size, ship.x + ship.dx));
    ship.y = Math.max(ship.size, Math.min(height - ship.size, ship.y + ship.dy));

    // Spawn asteroids
    if (Date.now() - lastSpawn > asteroidSpawnRate) {
      lastSpawn = Date.now();
      const radius = 15 + Math.random() * 20;
      const x = radius + Math.random() * (width - 2 * radius);
      asteroids.push({ x, y: -radius, radius, speed: asteroidSpeed + Math.random() });
    }

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // Remove if off-screen
      if (a.y - a.radius > height) asteroids.splice(i, 1);
    }

    // Collision detection (simple circle vs point approximation)
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.radius + ship.size / 2) {
        gameOver = true;
        break;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Draw ship as triangle
    ctx.fillStyle = 'cyan';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y - ship.size);
    ctx.lineTo(ship.x - ship.size / 2, ship.y + ship.size / 2);
    ctx.lineTo(ship.x + ship.size / 2, ship.y + ship.size / 2);
    ctx.closePath();
    ctx.fill();

    // Draw asteroids
    ctx.fillStyle = 'gray';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }

    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
